SELECT id, start_date, end_date, monthly_fee, status, MAX(monthly_fee) OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_monthly_fee, MIN(monthly_fee) OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_monthly_fee, CUME_DIST() OVER (PARTITION BY plan ORDER BY monthly_fee DESC NULLS LAST) monthly_fee_cume_dist FROM subscriptions
